class ListDirTool:
    name = "list_dir"
    description = "List files and directories inside the workspace."
    capability = ToolCapability.READ

    def schema(self) -> dict[str, Any]:
        return {
            "name": self.name,
            "description": self.description,
            "input_schema": {
