            return ToolResult(ok=False, content=f"workspace not found: {workspace}")

        try:
            completed = subprocess.run(
                raw_command,
                capture_output=True,
                text=True,
                shell=True,
                cwd=str(workspace),
                timeout=self._timeout,
            )
        except subprocess.TimeoutExpired:
            return ToolResult(
                ok=False,
                content=f"command timed out after {self._timeout}s: {raw_command[:200]}",
            )
        except Exception as exc:
            return ToolResult(ok=False, content=f"command failed: {exc}")

        output_parts = []
        if completed.stdout:
            output_parts.append(completed.stdout)
        if completed.stderr:
            output_parts.append(completed.stderr)

        output = "".join(output_parts)

        if len(output.encode("utf-8")) > self._max_output_bytes:
            output = output[: self._max_output_bytes] + "\n... (output truncated)"

        if completed.returncode != 0:
            return ToolResult(
                ok=True,
                content=f"Exit code: {completed.returncode}\n{output}",
            )

        return ToolResult(ok=True, content=output)

