import subprocess
from typing import Any

from app.permissions import ToolCapability
from app.tool_registry import ToolContext, ToolResult


class BashTool:
    name = "bash"
    description = "Execute a bash command in the workspace. Returns stdout, stderr, and exit code."
    capability = ToolCapability.EXECUTE

    def __init__(self, timeout: int = 30, max_output_bytes: int = 64_000) -> None:
        self._timeout = timeout
        self._max_output_bytes = max_output_bytes

    def schema(self) -> dict[str, Any]:
        return {
            "name": self.name,
            "description": self.description,
            "input_schema": {
                "type": "object",
                "properties": {
                    "command": {
                        "type": "string",
                        "description": "The bash command to execute",
                    },
                    "timeout": {
                        "type": "integer",
                        "description": "Timeout in seconds (overrides default if provided)",
                        "default": self._timeout,
                    },
                },
                "required": ["command"],
            },
        }

    def run(self, input: dict[str, Any], context: ToolContext) -> ToolResult:
        raw_command = input.get("command")
        if not isinstance(raw_command, str) or not raw_command.strip():
            return ToolResult(ok=False, content="command must be a non-empty string")

        timeout = input.get("timeout", self._timeout)
        if not isinstance(timeout, int) or timeout < 1:
            timeout = self._timeout

        try:
            completed = subprocess.run(
                raw_command,
                shell=True,
                capture_output=True,
                text=True,
                cwd=str(context.workspace),
                timeout=timeout,
            )
        except subprocess.TimeoutExpired:
            return ToolResult(
                ok=False,
                content=f"command timed out after {timeout}s: {raw_command[:200]}",
            )
        except Exception as exc:
            return ToolResult(ok=False, content=f"failed to execute command: {exc}")

        output_parts = []
        if completed.stdout:
            output_parts.append(completed.stdout)
        if completed.stderr:
            output_parts.append(f"[stderr]\n{completed.stderr}")

        output = "\n".join(output_parts)
        encoded = output.encode("utf-8")
        if len(encoded) > self._max_output_bytes:
            output = encoded[: self._max_output_bytes].decode("utf-8", errors="replace")
            output += "\n[truncated: output too large]"

        if completed.returncode != 0:
            return ToolResult(
                ok=False,
                content=f"exit code {completed.returncode}\n{output}" if output else f"exit code {completed.returncode}",
            )

        return ToolResult(ok=True, content=output or f"(completed with exit code 0)")

